<?php
namespace App\Models;
use App\Enums\WithdrawalStatus;use Illuminate\Database\Eloquent\Concerns\HasUlids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Database\Eloquent\Relations\HasOne;
class WithdrawalClaim extends Model
{use HasUlids;protected $fillable=['withdrawal_number','mitra_id','mitra_bank_account_id','submitted_by','amount','currency','status','idempotency_key','request_fingerprint','bank_snapshot','notes','reviewed_by','reviewed_at','approved_by','approved_at','rejected_by','rejected_at','rejection_reason','processing_by','processing_at','paid_by','paid_at','cancelled_by','cancelled_at','cancellation_reason'];protected function casts():array{return['amount'=>'decimal:2','status'=>WithdrawalStatus::class,'bank_snapshot'=>'array','reviewed_at'=>'datetime','approved_at'=>'datetime','rejected_at'=>'datetime','processing_at'=>'datetime','paid_at'=>'datetime','cancelled_at'=>'datetime'];}public function mitra():BelongsTo{return $this->belongsTo(Mitra::class);}public function bankAccount():BelongsTo{return $this->belongsTo(MitraBankAccount::class,'mitra_bank_account_id');}public function submitter():BelongsTo{return $this->belongsTo(User::class,'submitted_by');}public function transfer():HasOne{return $this->hasOne(WithdrawalTransfer::class);}public function journals():HasMany{return $this->hasMany(LedgerJournal::class);}}
